import hashlib
import time
import json
from typing import Dict, Any, Callable, Optional
from dataclasses import dataclass, field
from http import HTTPStatus

# --- Storage Abstraction ---

class CacheStore:
    """
    Abstract base class for cache storage.
    Allows swapping between in-memory, Redis, or other backends.
    """
    def get(self, key: str) -> Optional[Dict[str, Any]]:
        raise NotImplementedError

    def set(self, key: str, value: Dict[str, Any], ttl: int) -> None:
        raise NotImplementedError

class InMemoryCacheStore(CacheStore):
    """
    Simple in-memory implementation for development/testing.
    Thread-safety note: For production, a thread-safe implementation or 
    external store (like Redis) is recommended.
    """
    def __init__(self):
        self._store: Dict[str, Dict[str, Any]] = {}

    def get(self, key: str) -> Optional[Dict[str, Any]]:
        entry = self._store.get(key)
        if entry is None:
            return None
        # Check for expiry
        if time.time() > entry['expires_at']:
            # Lazy deletion
            del self._store[key]
            return None
        return entry['data']

    def set(self, key: str, value: Dict[str, Any], ttl: int) -> None:
        self._store[key] = {
            'data': value,
            'expires_at': time.time() + ttl
        }

# --- Configuration ---

@dataclass
class CacheConfig:
    default_ttl: int = 60
    cacheable_methods: tuple = (HTTPStatus.OK, HTTPStatus.NOT_MODIFIED) # Only cache 2xx responses
    bypass_methods: tuple = ("POST", "PUT", "DELETE", "PATCH")

# --- Middleware ---

class CacheMiddleware:
    def __init__(self, store: CacheStore, config: CacheConfig = None):
        self.store
